namespace NotificationApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the notification center!", new DateTime(2026, 7, 13, 8, 0, 0, DateTimeKind.Utc)),
        new(2, "Your profile was updated successfully.", new DateTime(2026, 7, 13, 9, 30, 0, DateTimeKind.Utc)),
        new(3, "New feature: dark mode is now available.", new DateTime(2026, 7, 13, 10, 15, 0, DateTimeKind.Utc)),
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>Returns notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public Task<List<Notification>> GetNewNotificationsSinceAsync(int sinceId)
    {
        lock (_lock)
        {
            // Simulate a ~20% chance of a new notification appearing each poll
            if (Random.Shared.Next(5) == 0)
            {
                var id = _nextId++;
                _notifications.Add(new Notification(id,
                    $"Something happened — notification #{id}",
                    DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Id > sinceId)
                              .OrderByDescending(n => n.Timestamp)
                              .ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var n in notifications)
        {
            <li>
                <strong>@n.Message</strong>
                <small>@n.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private CancellationTokenSource? _cts;

    // Persist across prerender → interactive so data isn't fetched twice
    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var sinceId = notifications?.Count > 0
                    ? notifications.Max(n => n.Id)
                    : 0;

                var newer = await NotificationService.GetNewNotificationsSinceAsync(sinceId);
                if (newer.Count > 0 && notifications is not null)
                {
                    notifications.InsertRange(0, newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

